import { spyOn, spy } from "./src/index.ts";

// Test 1: Own property method (should still work)
console.log("Test 1: Own property method");
const obj1 = { f: () => 'original' };
const s1 = spyOn(obj1, 'f');
s1.willCall(() => 'mocked');
console.log('  mocked:', obj1.f());
s1.restore();
console.log('  restored:', obj1.f());
const ownDesc1 = Object.getOwnPropertyDescriptor(obj1, 'f');
console.log('  has own prop:', ownDesc1 !== undefined, ownDesc1?.value?.() === 'original' ? 'PASS' : 'FAIL');

// Test 2: Prototype method (the bug case)
console.log("\nTest 2: Prototype method");
class Foo { f() { return 'original'; } }
const foo = new Foo();
const s2 = spyOn(foo, 'f');
s2.willCall(() => 'mocked');
console.log('  mocked:', foo.f());
s2.restore();
console.log('  restored:', foo.f());
console.log('  has own prop "f":', Object.getOwnPropertyDescriptor(foo, 'f') !== undefined ? 'FAIL' : 'PASS');

// Test 3: Deeper prototype chain
console.log("\nTest 3: Deep prototype chain");
class Base { f() { return 'base'; } }
class Mid extends Base {}
class Child extends Mid {}
const child = new Child();
const s3 = spyOn(child, 'f');
console.log('  mocked:', child.f());
s3.restore();
console.log('  restored:', child.f());
console.log('  has own prop "f":', Object.getOwnPropertyDescriptor(child, 'f') !== undefined ? 'FAIL' : 'PASS');

// Test 4: Restore is idempotent
console.log("\nTest 4: Restore idempotency");
class Cls { g() { return 'orig'; } }
const c = new Cls();
const s4 = spyOn(c, 'g');
s4.restore();
s4.restore(); // calling restore again shouldn't break
console.log('  double restored:', c.g());
console.log('  has own prop "g":', Object.getOwnPropertyDescriptor(c, 'g') !== undefined ? 'FAIL' : 'PASS');

// Test 5: Multiple spies on same prototype method (different instances)
console.log("\nTest 5: Multiple instances sharing prototype");
class Shared { method() { return 'shared'; } }
const inst1 = new Shared();
const inst2 = new Shared();
const s5a = spyOn(inst1, 'method');
const s5b = spyOn(inst2, 'method');
s5a.restore();
console.log('  inst1 after restore:', inst1.method());
console.log('  inst1 has own prop:', Object.getOwnPropertyDescriptor(inst1, 'method') !== undefined ? 'FAIL' : 'PASS');
console.log('  inst2 still mocked:', inst2.method());
s5b.restore();
console.log('  inst2 after restore:', inst2.method());
console.log('  inst2 has own prop:', Object.getOwnPropertyDescriptor(inst2, 'method') !== undefined ? 'FAIL' : 'PASS');

// Test 6: restoreAll
console.log("\nTest 6: restoreAll with prototype methods");
import { restoreAll } from "./src/index.ts";
class R { m() { return 'r'; } }
const r1 = new R();
const r2 = new R();
spyOn(r1, 'm');
spyOn(r2, 'm');
restoreAll();
console.log('  r1 after restoreAll:', r1.m());
console.log('  r1 has own prop:', Object.getOwnPropertyDescriptor(r1, 'm') !== undefined ? 'FAIL' : 'PASS');
console.log('  r2 after restoreAll:', r2.m());
console.log('  r2 has own prop:', Object.getOwnPropertyDescriptor(r2, 'm') !== undefined ? 'FAIL' : 'PASS');

console.log("\nAll edge case tests complete.");

